UNIT_NAMES = {"und": "Unidad", "kg": "Kilogramo", "ton": "Tonelada", "bulto": "Bulto", "m3": "Metro cúbico"}


def assign_to_companies(apps, schema_editor):
    """Tipos, unidades y marcas pasan a ser de cada empresa (Hurgo no los crea).

    - Unidades: cada empresa recibe como suyas las que usan sus productos (antes era una lista fija).
    - Tipos y marcas sin empresa: pasan a la empresa que los usa; si los usan varias, cada una
      recibe su copia y sus productos (y viajes, en el caso de la marca) apuntan a ella.
    """
    M_unit = apps.get_model("orders", "M_unit")
    M_item = apps.get_model("orders", "M_item")
    M_type_item = apps.get_model("orders", "M_type_item")
    M_brand = apps.get_model("orders", "M_brand")
    M_trip = apps.get_model("trips", "M_trip")

    for item in M_item.objects.all():
        symbol = item.unit or "und"
        unit, _ = M_unit.objects.get_or_create(company_id_id=item.company_id_id, symbol=symbol,
                                               defaults={"name": UNIT_NAMES.get(symbol, symbol)})
        item.unit_id = unit
        item.save(update_fields=["unit_id"])

    def split(model, field, trips=False):
        for obj in model.objects.filter(company_id__isnull=True):
            companies = sorted(set(M_item.objects.filter(**{field: obj}).values_list("company_id", flat=True)))
            if not companies:
                continue
            original_pk = obj.pk
            obj.company_id_id = companies[0]
            obj.save()
            for company_id in companies[1:]:
                copy = model.objects.get(pk=original_pk)
                copy.pk = None
                copy.id = None
                copy.company_id_id = company_id
                copy.save()
                M_item.objects.filter(**{field: original_pk}, company_id=company_id).update(**{field: copy.pk})
                if trips:
                    M_trip.objects.filter(brand_id=original_pk, company_id=company_id).update(brand_id=copy.pk)

    split(M_type_item, "type_item_id")
    split(M_brand, "brand_id", trips=True)


